// The outlined "stack neverflow" wordmark (brand board lettering, generated by scripts/gen_wordmark.py),
// drawn from vector data so it needs no font.
#pragma once

#include <windows.h>

namespace wp {

class Canvas;

// Size in px of the wordmark drawn `height` px tall (ascender top to the lowest overshoot).
SIZE WordmarkSize(int height);
// Draws it with its top-left at (x, y).
void DrawWordmark(Canvas& c, int x, int y, int height, COLORREF color);

}  // namespace wp
